import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence, useScroll, useTransform, useSpring, useMotionValue } from 'framer-motion';
import { Play, ArrowUpRight, Instagram, Mail, ChevronRight, Zap, Briefcase, Award, Sparkles, Send, Check, Loader2, Wand2, Bot, Github } from 'lucide-react';
import './App.css'; 

// --- COMPONENTS ---

// UPDATED: Logo Black for Light Mode
const AuraLogo = React.memo(({ className = "w-8 h-8" }) => (
  <svg viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" className={className}>
    <motion.path 
      d="M50 5 L95 80 L5 80 Z" 
      stroke="#000000" 
      strokeWidth="4" 
      strokeLinecap="round" 
      strokeLinejoin="round"
      initial={{ pathLength: 0 }}
      animate={{ pathLength: 1 }}
      transition={{ duration: 2, ease: "easeInOut" }}
    />
    <motion.path 
      d="M50 30 L75 70 L25 70 Z" 
      fill="#000000"
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 0.1, scale: 1 }}
      transition={{ delay: 1, duration: 1 }}
    />
  </svg>
));

// UPDATED: Black Cursor
const CustomCursor = React.memo(() => {
  const cursorX = useMotionValue(-100);
  const cursorY = useMotionValue(-100);
  const ringX = useMotionValue(-100);
  const ringY = useMotionValue(-100);
  const [isHovering, setIsHovering] = useState(false);
  
  const springConfig = { damping: 25, stiffness: 700, mass: 0.1 };
  const cursorXSpring = useSpring(cursorX, springConfig);
  const cursorYSpring = useSpring(cursorY, springConfig);
  const ringXSpring = useSpring(ringX, { damping: 30, stiffness: 200, mass: 0.5 });
  const ringYSpring = useSpring(ringY, { damping: 30, stiffness: 200, mass: 0.5 });

  useEffect(() => {
    const moveCursor = (e) => {
      cursorX.set(e.clientX - 4); cursorY.set(e.clientY - 4);
      ringX.set(e.clientX - 16); ringY.set(e.clientY - 16);
    };
    const handleMouseOver = (e) => setIsHovering(!!e.target.closest('a, button, input, textarea, .interactive'));
    window.addEventListener('mousemove', moveCursor);
    window.addEventListener('mouseover', handleMouseOver);
    return () => { window.removeEventListener('mousemove', moveCursor); window.removeEventListener('mouseover', handleMouseOver); };
  }, [cursorX, cursorY, ringX, ringY]);

  return (
    <>
      <motion.div className="custom-cursor fixed top-0 left-0 w-2 h-2 bg-black rounded-full pointer-events-none z-[100]" style={{ x: cursorXSpring, y: cursorYSpring, scale: isHovering ? 0 : 1 }} />
      <motion.div className="custom-cursor fixed top-0 left-0 w-8 h-8 border border-black/30 rounded-full pointer-events-none z-[99]" style={{ x: ringXSpring, y: ringYSpring, scale: isHovering ? 1.5 : 1, backgroundColor: isHovering ? 'rgba(0,0,0,0.05)' : 'transparent', borderColor: isHovering ? 'transparent' : 'rgba(0,0,0,0.3)' }} transition={{ duration: 0.2 }} />
    </>
  );
});

const MagneticButton = React.memo(({ children, className, onClick, primary = false }) => {
  const ref = useRef(null);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const handleMouse = (e) => {
    const { clientX, clientY } = e;
    const { height, width, left, top } = ref.current.getBoundingClientRect();
    setPosition({ x: (clientX - (left + width/2)) * 0.2, y: (clientY - (top + height/2)) * 0.2 });
  };
  return (
    <motion.button ref={ref} onMouseMove={handleMouse} onMouseLeave={() => setPosition({ x: 0, y: 0 })} animate={{ x: position.x, y: position.y }} transition={{ type: "spring", stiffness: 150, damping: 15 }} whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.98 }} onClick={onClick} className={`relative overflow-hidden rounded-full group interactive transition-shadow duration-300 ${primary ? 'bg-black text-white font-semibold shadow-lg hover:shadow-xl' : 'bg-white/60 border border-black/10 text-black backdrop-blur-md hover:bg-white/80'} ${className}`}>
      <span className="relative z-10 flex items-center justify-center gap-2">{children}</span>
    </motion.button>
  );
});

// UPDATED: Glass Cards for Light Mode
const TiltCard = React.memo(({ children, className }) => {
  const ref = useRef(null);
  const x = useMotionValue(0); const y = useMotionValue(0);
  const mouseXSpring = useSpring(x, { stiffness: 300, damping: 30 });
  const mouseYSpring = useSpring(y, { stiffness: 300, damping: 30 });
  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["10deg", "-10deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-10deg", "10deg"]);

  return (
    <motion.div ref={ref} onMouseMove={(e) => { 
        const rect = ref.current.getBoundingClientRect(); 
        x.set((e.clientX - rect.left) / rect.width - 0.5); 
        y.set((e.clientY - rect.top) / rect.height - 0.5); 
      }} onMouseLeave={() => { x.set(0); y.set(0); }} 
      style={{ rotateX, rotateY, transformStyle: "preserve-3d", boxShadow: "0 20px 50px rgba(0,0,0,0.1), inset 0 0 0 1px rgba(255,255,255,0.8)" }} 
      className={`relative rounded-[24px] bg-white/40 backdrop-blur-[20px] p-8 transition-colors hover:bg-white/60 interactive border border-white/60 ${className}`}>
      <div style={{ transform: "translateZ(40px)", transformStyle: "preserve-3d" }} className="w-full h-full">{children}</div>
      <motion.div className="absolute inset-0 rounded-[24px] pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500" style={{ background: useTransform([mouseXSpring, mouseYSpring], ([mx, my]) => `radial-gradient(circle at ${(mx + 0.5)*100}% ${(my + 0.5)*100}%, rgba(255, 255, 255, 0.8), transparent 60%)`) }} />
    </motion.div>
  );
});

const SectionHeading = React.memo(({ children, subtitle }) => (
  <motion.div initial={{ opacity: 0, y: 30 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, margin: "-100px" }} transition={{ duration: 0.8 }} className="mb-16">
    {subtitle && <h4 className="text-black/60 font-semibold tracking-wider uppercase text-sm mb-3 flex items-center gap-2"><Sparkles className="w-4 h-4 text-black" /> {subtitle}</h4>}
    <h2 className="text-4xl md:text-6xl font-bold tracking-tighter text-black">{children}</h2>
  </motion.div>
));

const Loader = React.memo(({ onComplete }) => (
  <motion.div key="loader" exit={{ opacity: 0 }} transition={{ duration: 1 }} className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-[#F7F9FC]">
    <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="flex flex-col items-center">
      <AuraLogo className="w-20 h-20 mb-6" />
      <motion.h1 initial={{ y: 40 }} animate={{ y: 0 }} transition={{ delay: 0.5, duration: 0.8 }} className="text-3xl tracking-[0.3em] font-light text-black">AURA</motion.h1>
    </motion.div>
    <motion.div initial={{ width: 0 }} animate={{ width: "200px" }} transition={{ delay: 1, duration: 1.5 }} onAnimationComplete={onComplete} className="h-[1px] bg-gradient-to-r from-transparent via-black/50 to-transparent mt-8" />
  </motion.div>
));

const callGeminiAPI = async (prompt, systemPrompt) => {
  /* Using standard fetch with delays for demo stability */
  const apiKey = ""; 
  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-preview-09-2025:generateContent?key=${apiKey}`;
  const payload = { contents: [{ parts: [{ text: prompt }] }], systemInstruction: { parts: [{ text: systemPrompt }] } };
  for (let i = 0; i < 3; i++) { try { const r = await fetch(url, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(payload) }); if(r.ok) { const d = await r.json(); return d.candidates?.[0]?.content?.parts?.[0]?.text || "No output."; } } catch(e){} await new Promise(r => setTimeout(r, 1000)); } return "AI is busy.";
};

